"""Integration checks for results generated by main.py; no fitting in tests."""

import subprocess
import sys
from datetime import date
from pathlib import Path

import pandas as pd
import pytest
from app import METHODS, WORKSPACES
from src.runner import current_result
from streamlit.testing.v1 import AppTest

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_APP_TIMEOUT = 180
EXPECTED_WORKSPACE_COUNT = 8

pytestmark = pytest.mark.skipif(
    not (ROOT / "results/run_summary.csv").is_file(),
    reason="Run python main.py before dashboard integration tests.",
)


@pytest.fixture(scope="module")
def app():
    assert current_result(ROOT) is not None
    instance = AppTest.from_file(
        str(ROOT / "app.py"), default_timeout=DEFAULT_APP_TIMEOUT
    ).run()
    assert not instance.exception
    return instance


def assert_complete(app):
    assert not app.exception
    assert len(app.sidebar.radio) == 1
    assert list(app.sidebar.radio[0].options) == WORKSPACES
    assert len(WORKSPACES) == EXPECTED_WORKSPACE_COUNT
    assert not any(
        "missing, incomplete or inconsistent" in item.value for item in app.error
    )


def select_workspace(app, name):
    return app.sidebar.radio(key="workspace").set_value(name).run()


def test_default_selected_procedure(app):
    assert_complete(app)
    assert app.sidebar.radio(key="workspace").value == "Executive Overview"
    assert app.selectbox(key="final_method").value == "garch_t"
    assert app.selectbox(key="final_confidence").value == 0.99
    assert not any(item.key == "final_strategy" for item in app.selectbox)
    assert any("HOLD / NO TRADE" in item.value for item in app.error)


@pytest.mark.parametrize("confidence", [0.9, 0.95, 0.99])
def test_all_method_confidence_combinations(app, confidence):
    select_workspace(app, "Executive Overview")
    for method in METHODS:
        app.selectbox(key="final_method").set_value(method)
        app.selectbox(key="final_confidence").set_value(confidence).run()
        assert_complete(app)


@pytest.mark.parametrize("cost", [0.0, 5.0, 10.0])
def test_cost_and_full_decision_map(app, cost):
    select_workspace(app, "Funding & Performance")
    app.selectbox(key="final_cost").set_value(cost).run()
    assert_complete(app)


@pytest.mark.parametrize("spending", [0.0, 0.02, 0.03, 0.04])
def test_spending_controls(app, spending):
    select_workspace(app, "Funding & Performance")
    app.selectbox(key="gmv_spend").set_value(spending).run()
    assert_complete(app)


def test_dates_and_evidence_downloads(app):
    select_workspace(app, "Backtesting & Model Validation")
    app.date_input(key="final_dates").set_value(
        (date(2026, 10, 22), date(2026, 10, 23))
    ).run()
    assert not app.exception
    assert any("at least 20" in item.value for item in app.info)
    app.date_input(key="final_dates").set_value(
        (date(2022, 1, 3), date(2022, 12, 30))
    ).run()
    assert_complete(app)
    select_workspace(app, "Funding & Performance")
    keys = {item.key for item in app.get("download_button")}
    assert "gmv_baseline_download" in keys


def test_startup_never_downloads_or_fits(monkeypatch):
    import arch.univariate.base
    import requests

    # Guard against accidental network calls or GARCH refits during Streamlit render.
    def forbidden(*args, **kwargs):
        raise AssertionError(
            "Unexpected network request or research fit during app startup"
        )

    monkeypatch.setattr(requests.sessions.Session, "request", forbidden)
    monkeypatch.setattr(arch.univariate.base.ARCHModel, "fit", forbidden)
    instance = AppTest.from_file(
        str(ROOT / "app.py"), default_timeout=DEFAULT_APP_TIMEOUT
    ).run()
    assert_complete(instance)


def test_empty_result_is_explicit(monkeypatch):
    import app as dashboard

    def empty(*args, **kwargs):
        raise pd.errors.EmptyDataError("Synthetic empty result")

    monkeypatch.setattr(dashboard, "_tables", empty)
    instance = AppTest.from_string(
        "import app\napp.main()", default_timeout=DEFAULT_APP_TIMEOUT
    ).run()
    assert not instance.exception
    assert any("cannot be used" in item.value for item in instance.error)


def test_main_verification_and_cache_reuse():
    for args in [["--verify"], []]:
        process = subprocess.run(
            [sys.executable, str(ROOT / "main.py"), *args],
            capture_output=True,
            text=True,
            timeout=60,
        )
        assert process.returncode == 0, process.stderr
        if not args:
            assert "Reusing verified flat results in results/." in process.stderr
            assert "Recomputing" not in process.stderr


def test_completed_run_creates_csv_outputs_only():
    path = current_result(ROOT)
    assert path is not None
    assert all(
        item.suffix == ".csv"
        for item in path.iterdir()
        if item.is_file() and not item.name.startswith(".")
    )
    assert not any(
        item.suffix.lower() in {".json", ".jsonl", ".toml"}
        for item in (ROOT / "results").rglob("*")
    )


def test_review_decision_evidence_and_sizing_controls(app):
    for workspace in WORKSPACES:
        select_workspace(app, workspace)
        assert_complete(app)
    select_workspace(app, "Assumptions & Limitations")
    keys = {item.key for item in app.get("download_button")}
    assert "gmv_table_download" in keys
